"""Export alerts or rule coverage as a MITRE ATT&CK Navigator layer (v4.5 layer format)."""
from __future__ import annotations

import json
from collections import Counter


def build_layer(technique_counts: Counter, name: str = "detect-engine coverage") -> dict:
    top = max(technique_counts.values(), default=1)
    return {
        "name": name,
        "versions": {"attack": "15", "navigator": "4.9.5", "layer": "4.5"},
        "domain": "enterprise-attack",
        "description": "Generated by detect-engine",
        "gradient": {"colors": ["#ffffff", "#ff6666"], "minValue": 0, "maxValue": top},
        "techniques": [
            {"techniqueID": t, "score": n, "comment": f"{n} hit(s)"} for t, n in sorted(technique_counts.items())
        ],
    }


def dumps(technique_counts: Counter, name: str = "detect-engine coverage") -> str:
    return json.dumps(build_layer(technique_counts, name), indent=2)
